/* ============================== SUBSCRIPTION BUNDLE ============================== */
const newBun=()=>({on:false,ids:[],disc:0.2,fam:false,sh:0,start:null,subs:0,rev:0,peak:0,log:[]});
const BUN_D=[0.1,0.2,0.3,0.4];
const bunName=()=>(G.name||(LANG_EN?"Company":'Şirket')).split(' ')[0]+(LANG_EN?" One":' One');
const bunElig=()=>myActive().filter(p=>isSubP(p));
const bunProds=()=>{const B=G.bun;return B&&B.on?B.ids.map(id=>prod(id)).filter(p=>p&&p.active&&p.owner==='P'):[];};
const bunIn=p=>{const B=G.bun;return !!(B&&B.on&&p.owner==='P'&&B.ids.includes(p.id));};
function bunTarget(){const B=G.bun,n=bunProds().length;if(n<2)return 0;return clamp((0.08+B.disc*0.9+0.05*(n-2)+(B.fam?0.08:0))*(0.7+G.brand/300),0,0.6);}
const bunChurn=p=>bunIn(p)?1-(G.bun.fam?0.5:0.4)*G.bun.sh:1;
const bunRev=p=>bunIn(p)?1-G.bun.sh*(1-(1-G.bun.disc)*(G.bun.fam?0.75:1)):1;
function bunApp(p){if(!bunIn(p))return 1;const B=G.bun,n=bunProds().length;return 1+(0.03*(n-1)+0.3*B.disc)*Math.min(1,B.sh/0.3+0.3);}
const bunList=()=>bunProds().reduce((a,p)=>a+p.price,0);
const bunPrice=()=>bunList()*(1-G.bun.disc)*(G.bun.fam?1.5:1);
function bunLog(t,k=''){const B=G.bun;B.log.unshift({d:G.day,t,k});if(B.log.length>10)B.log.pop();}
function bunMonthly(){const B=G.bun;if(!B||!B.on)return;const P=bunProds();
  if(P.length<2){B.on=false;B.sh=0;news((LANG_EN?`The ${bunName()} bundle no longer has enough products; the bundle was closed.`:`${bunName()} paketinde yeterli ürün kalmadı; paket kapatıldı.`),'bad',true);bunLog((LANG_EN?"Bundle closed: not enough products left.":'Paket kapatıldı: yeterli ürün kalmadı.'),'bad');return;}
  B.sh+=(bunTarget()-B.sh)*0.12;B.subs=Math.round(Math.max(...P.map(p=>payers(p)))*B.sh);B.rev=B.subs*bunPrice();B.peak=Math.max(B.peak,B.subs);
  if(P.length>=3)G.brand=clamp(G.brand+0.02*P.length,0,100);}
function bunSet(ids,disc,fam){const B=G.bun,old=B.on?{n:bunProds().length,disc:B.disc}:null;B.ids=ids;B.disc=disc;B.fam=fam;
  if(old){if(ids.length<old.n){B.sh*=0.8;for(const p of bunProds())if(p.sat!=null)p.sat=Math.max(0,p.sat-3);bunLog((LANG_EN?"A product was removed from the bundle; subscribers are unhappy.":'Paketten ürün çıkarıldı; aboneler hoşnutsuz.'),'bad');}
    if(disc<old.disc-1e-9){B.sh*=0.85;if(G.soc)G.soc.s=clamp(G.soc.s-6,-100,100);bunLog((LANG_EN?`Bundle discount cut to ${Math.round(disc*100)}%; some subscribers left.`:`Paket indirimi %${Math.round(disc*100)}'e düşürüldü; abonelerin bir kısmı ayrıldı.`),'bad');}}}
function vBundle(){const B=G.bun,E=bunElig(),nm=bunName();
  if(E.length<2&&!B.on)return (LANG_EN?`<section class="panel"><div class="ph"><h2>Subscription bundle${helpBtn('bundle')}</h2></div><div class="pb"><p class="small muted">Once you have at least two subscription-based software products (paid or freemium app, enterprise software, AI service), you can set up a bundle offering them all at one price. You currently have ${E.length} eligible products.</p></div></section>`:`<section class="panel"><div class="ph"><h2>Abonelik paketi${helpBtn('bundle')}</h2></div><div class="pb"><p class="small muted">Aboneliğe dayalı en az iki yazılım ürünün (ücretli ya da freemium uygulama, kurumsal yazılım, yapay zekâ hizmeti) olduğunda hepsini tek fiyatla sunan bir paket kurabilirsin. Şu an ${E.length} uygun ürünün var.</p></div></section>`);
  const sel=UI.bunSel||(UI.bunSel={ids:B.on?[...B.ids]:E.slice(0,4).map(p=>p.id),disc:B.disc,fam:B.fam});sel.ids=sel.ids.filter(id=>E.some(p=>p.id===id));
  const P=bunProds(),list=E.filter(p=>sel.ids.includes(p.id)).reduce((a,p)=>a+p.price,0),pr=list*(1-sel.disc)*(sel.fam?1.5:1),dirty=!B.on||sel.disc!==B.disc||sel.fam!==B.fam||sel.ids.slice().sort().join()!==B.ids.slice().sort().join();
  const tog=E.map(p=>{const on=sel.ids.includes(p.id);return `<button class="btn sm bun-tg${on?' on':''}" data-act="bunpick" data-id="${p.id}" aria-pressed="${on}">${on?'✓ ':''}${esc(p.name)} <span class="muted">${money(p.price)}</span></button>`;}).join('');
  const rows=P.map(p=>{const c0=churnOf(p)/bunChurn(p);return (LANG_EN?`<tr><td><b>${esc(p.name)}</b><div class="small muted">${CATS[p.cat].n}</div></td><td class="r num">${num(Math.round(payers(p)))}</td><td class="r num">${fx(c0*100,1)}% → <b>${fx(churnOf(p)*100,1)}%</b></td><td class="r num">+${fx((bunApp(p)-1)*100,1)}%</td><td class="r num ${bunRev(p)<1?'neg':''}">${bunRev(p)<1?'−':'+'}${fx(Math.abs(1-bunRev(p))*100,1)}%</td></tr>`:`<tr><td><b>${esc(p.name)}</b><div class="small muted">${CATS[p.cat].n}</div></td><td class="r num">${num(Math.round(payers(p)))}</td><td class="r num">%${fx(c0*100,1)} → <b>%${fx(churnOf(p)*100,1)}</b></td><td class="r num">+%${fx((bunApp(p)-1)*100,1)}</td><td class="r num ${bunRev(p)<1?'neg':''}">${bunRev(p)<1?'−':'+'}%${fx(Math.abs(1-bunRev(p))*100,1)}</td></tr>`);}).join('');
  return (LANG_EN?`<section class="panel"><div class="ph"><h2>${esc(nm)}${helpBtn('bundle')}</h2><span class="sub">${B.on?`Since ${fmtDate(B.start)} · ${P.length} products`:"Not started yet"}</span></div>
    ${B.on?`<div class="kpis" style="border-top:0"><div class="kpi"><span>Bundle subscribers</span><b>${num(B.subs)}</b></div><div class="kpi"><span>Bundle price</span><b>${money(bunPrice())}/mo</b></div><div class="kpi"><span>Bundle revenue</span><b>${money(B.rev)}/mo</b></div><div class="kpi"><span>Adoption</span><b>${Math.round(B.sh*100)}%</b><span class="small muted"> target ${Math.round(bunTarget()*100)}%</span></div></div>`:''}
    <div class="pb col"><p class="small muted">A bundle ties together the subscribers of its products: churn drops, the products become more appealing, and users try your other products too. In return, subscribers who switch to the bundle pay a discounted price. The bigger the discount, the higher the adoption; a family plan raises the price 1.5x but groups several paying users into one account: more people switch, churn drops further, and revenue per user falls.</p>
      <div class="col" style="gap:6px"><b class="small">Products in the bundle</b><div class="row" style="gap:6px;flex-wrap:wrap">${tog}</div></div>
      <div class="col" style="gap:6px"><b class="small">Discount</b><div class="row" style="gap:6px;flex-wrap:wrap" role="group" aria-label="Bundle discount">${BUN_D.map(d=>`<button class="btn sm${sel.disc===d?' primary':''}" data-act="bundisc" data-k="${d}" aria-pressed="${sel.disc===d}">${Math.round(d*100)}%</button>`).join('')}<button class="btn sm${sel.fam?' primary':''}" data-act="bunfam" aria-pressed="${sel.fam}">Family plan: ${sel.fam?"On":"Off"}</button></div></div>
      <div class="row between" style="gap:8px;flex-wrap:wrap"><span class="small">Separately <s>${money(list)}</s> → bundle <b>${money(pr)}/mo</b> · ${sel.ids.length} products</span>
        <span class="row" style="gap:6px">${B.on?`<button class="btn sm primary" data-act="bungo" ${!dirty||sel.ids.length<2?'disabled':''}>Apply changes</button><button class="btn sm ghost" data-act="bunoff">Close bundle</button>`:`<button class="btn sm primary" data-act="bungo" ${sel.ids.length<2?'disabled':''}>Launch ${esc(nm)} bundle</button>`}</span></div>
      ${B.on&&rows?`<div class="tw"><table class="rt"><thead><tr><th>Product</th><th class="r">Paying</th><th class="r">Monthly churn</th><th class="r">Appeal</th><th class="r">Revenue per user</th></tr></thead><tbody>${rows}</tbody></table></div>`:''}
      ${B.log.length?`<ul class="alerts">${B.log.map(l=>`<li><span class="small muted num" style="min-width:86px">${fmtDate(l.d)}</span><span class="${l.k==='bad'?'neg':l.k==='good'?'pos':''}">${esc(l.t)}</span></li>`).join('')}</ul>`:''}</div></section>`:`<section class="panel"><div class="ph"><h2>${esc(nm)}${helpBtn('bundle')}</h2><span class="sub">${B.on?`${fmtDate(B.start)} tarihinden beri · ${P.length} ürün`:'Henüz başlatılmadı'}</span></div>
    ${B.on?`<div class="kpis" style="border-top:0"><div class="kpi"><span>Paket abonesi</span><b>${num(B.subs)}</b></div><div class="kpi"><span>Paket fiyatı</span><b>${money(bunPrice())}/ay</b></div><div class="kpi"><span>Paket geliri</span><b>${money(B.rev)}/ay</b></div><div class="kpi"><span>Benimseme</span><b>%${Math.round(B.sh*100)}</b><span class="small muted"> hedef %${Math.round(bunTarget()*100)}</span></div></div>`:''}
    <div class="pb col"><p class="small muted">Paket, içindeki ürünlerin abonelerini birbirine bağlar: kayıp oranı düşer, ürünler daha çekici olur ve kullanıcılar diğer ürünlerini de dener. Karşılığında pakete geçen aboneler indirimli öder. İndirim büyüdükçe benimseme artar; aile planı fiyatı 1,5 katına çıkarır ama birden çok ödeyen kullanıcı tek hesapta toplanır: daha çok kişi geçer, kayıp daha da azalır, kullanıcı başı gelir düşer.</p>
      <div class="col" style="gap:6px"><b class="small">Paketteki ürünler</b><div class="row" style="gap:6px;flex-wrap:wrap">${tog}</div></div>
      <div class="col" style="gap:6px"><b class="small">İndirim</b><div class="row" style="gap:6px;flex-wrap:wrap" role="group" aria-label="Paket indirimi">${BUN_D.map(d=>`<button class="btn sm${sel.disc===d?' primary':''}" data-act="bundisc" data-k="${d}" aria-pressed="${sel.disc===d}">%${Math.round(d*100)}</button>`).join('')}<button class="btn sm${sel.fam?' primary':''}" data-act="bunfam" aria-pressed="${sel.fam}">Aile planı: ${sel.fam?'Açık':'Kapalı'}</button></div></div>
      <div class="row between" style="gap:8px;flex-wrap:wrap"><span class="small">Ayrı ayrı <s>${money(list)}</s> → paket <b>${money(pr)}/ay</b> · ${sel.ids.length} ürün</span>
        <span class="row" style="gap:6px">${B.on?`<button class="btn sm primary" data-act="bungo" ${!dirty||sel.ids.length<2?'disabled':''}>Değişiklikleri uygula</button><button class="btn sm ghost" data-act="bunoff">Paketi kapat</button>`:`<button class="btn sm primary" data-act="bungo" ${sel.ids.length<2?'disabled':''}>${esc(nm)} paketini başlat</button>`}</span></div>
      ${B.on&&rows?`<div class="tw"><table class="rt"><thead><tr><th>Ürün</th><th class="r">Ödeyen</th><th class="r">Aylık kayıp</th><th class="r">Cazibe</th><th class="r">Kullanıcı başı gelir</th></tr></thead><tbody>${rows}</tbody></table></div>`:''}
      ${B.log.length?`<ul class="alerts">${B.log.map(l=>`<li><span class="small muted num" style="min-width:86px">${fmtDate(l.d)}</span><span class="${l.k==='bad'?'neg':l.k==='good'?'pos':''}">${esc(l.t)}</span></li>`).join('')}</ul>`:''}</div></section>`);}

